"""Evaluate answers generated by the live RAGSystem with a grounded Qwen judge."""

import json
import re
import sys
import time
from pathlib import Path

import httpx
from openai import OpenAI

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from base import Config
from rag_qa.core.new_rag_system import RAGSystem
from rag_qa.core.vector_store import VectorStore

DATASET = ROOT / "RETAILRAG_RAG_EVALUATION_SET.json"
OUT = ROOT / "RETAILRAG_GENERATION_EVALUATION.json"

SAMPLE_COUNTS = {
    "single_document": 6,
    "multi_document": 6,
    "keyword_exact": 5,
    "semantic_paraphrase": 5,
    "version_conflict": 4,
    "unanswerable": 4,
    "multiturn": 2,
}


def parse_json(text):
    match = re.search(r"\{.*\}", text, re.S)
    if not match:
        raise ValueError(f"judge returned non-JSON: {text[:200]}")
    return json.loads(match.group(0))


def main():
    config = Config()
    client = OpenAI(
        api_key=config.DASHSCOPE_API_KEY,
        base_url=config.DASHSCOPE_BASE_URL,
        http_client=httpx.Client(trust_env=False, timeout=60),
    )

    def llm_stream(prompt):
        completion = client.chat.completions.create(
            model=config.LLM_MODEL,
            messages=[
                {"role": "system", "content": "你是 Nova Retail 智能知识助手。"},
                {"role": "user", "content": prompt},
            ],
            temperature=0.1,
            timeout=60,
            stream=True,
        )
        for chunk in completion:
            if chunk.choices and chunk.choices[0].delta.content:
                yield chunk.choices[0].delta.content

    dataset = json.loads(DATASET.read_text(encoding="utf-8"))["samples"]
    samples = []
    for qtype, count in SAMPLE_COUNTS.items():
        samples.extend([row for row in dataset if row["question_type"] == qtype][:count])

    rag = RAGSystem(VectorStore(), llm_stream)
    results = []
    for index, sample in enumerate(samples, 1):
        answer = "".join(
            rag.generate_answer(
                sample["question"], history=sample.get("history", [])
            )
        )
        trace = rag.last_generation_trace or {}
        context = trace.get("final_context") or "（无检索上下文）"
        judge_prompt = f"""你是 RAG 评测裁判。只能根据提供内容评分，不补充外部事实。
对每项给 0 到 1：
- faithfulness：实际回答中的事实是否都能由检索上下文支持；正确拒答且无上下文时计 1。
- answer_relevance：是否直接回应问题；期望拒答时，明确知识不足才算相关。
- context_precision：检索上下文中与问题直接有关的比例；正确无上下文拒答计 1。
- context_recall：检索上下文是否覆盖参考答案所需事实；期望拒答且无上下文计 1。
只输出 JSON：{{"faithfulness":0,"answer_relevance":0,"context_precision":0,"context_recall":0,"rationale":"简短理由"}}

问题：{sample['question']}
期望行为：{sample['expected_behavior']}
参考答案：{sample['ground_truth']}
检索上下文：{context[:10000]}
实际回答：{answer}"""
        judged = None
        error = None
        try:
            response = client.chat.completions.create(
                model=config.LLM_MODEL,
                messages=[{"role": "user", "content": judge_prompt}],
                temperature=0.0,
                timeout=60,
            )
            judged = parse_json(response.choices[0].message.content)
            for key in ("faithfulness", "answer_relevance", "context_precision", "context_recall"):
                judged[key] = max(0.0, min(1.0, float(judged[key])))
        except Exception as exc:
            error = str(exc)
        results.append(
            {
                "id": sample["id"],
                "question_type": sample["question_type"],
                "question": sample["question"],
                "expected_behavior": sample["expected_behavior"],
                "reference_documents": sample["reference_documents"],
                "answer": answer,
                "retrieved_documents": trace.get("references", []),
                "rewritten_query": trace.get("rewritten_query"),
                "evidence_decision": trace.get("evidence_decision"),
                "llm_called": trace.get("llm_called"),
                "scores": judged,
                "judge_error": error,
            }
        )
        print(f"generation: {index}/{len(samples)}", flush=True)

    valid = [row for row in results if row["scores"]]
    metric_names = ("faithfulness", "answer_relevance", "context_precision", "context_recall")
    metrics = {
        name: round(sum(row["scores"][name] for row in valid) / len(valid), 6)
        for name in metric_names
    } if valid else {}
    refusal_rows = [row for row in results if row["expected_behavior"] == "reject"]
    refusal_accuracy = sum(
        "当前知识库信息不足" in row["answer"] for row in refusal_rows
    ) / len(refusal_rows) if refusal_rows else 0.0
    output = {
        "status": "PASS" if len(valid) == len(results) else "PARTIAL",
        "framework": "Qwen grounded LLM-as-judge over live RAGSystem outputs",
        "ragas_status": "NOT_USED_DIRECTLY",
        "ragas_note": "The installed RAGAS 0.3 stack was not used directly; the existing authenticated Qwen endpoint was used for a deterministic four-dimension grounded judge.",
        "sample_count": len(results),
        "successfully_judged": len(valid),
        "metrics": metrics,
        "unanswerable_refusal_accuracy": round(refusal_accuracy, 6),
        "results": results,
        "generated_at_epoch": time.time(),
    }
    OUT.write_text(json.dumps(output, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps({key: output[key] for key in ("status", "framework", "sample_count", "successfully_judged", "metrics", "unanswerable_refusal_accuracy")}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
